    "lengthTier": "medium",
    "wordCountVi": 149,
    "textVi": "Chào buổi tối quý vị. Tối nay trên Vietnam Today, chúng tôi phản ánh sự bùng nổ kim ngạch xuất khẩu ấn tượng của trái cây nhiệt đới Việt Nam tại các hệ thống siêu thị quốc tế cao cấp. Nhờ sức hút mạnh mẽ của giống sầu riêng Ri6 cơm vàng hạt lép, xoài cát chu thơm nức và thanh long ruột đỏ, xuất khẩu rau quả đã vượt qua những kỷ lục lịch sử. Các hợp tác xã tại miền Tây và Tây Nguyên tuân thủ nghiêm ngặt chuẩn GlobalGAP, gắn mã QR số hóa giúp truy vết từng quả ngọt về tận vườn cây nơi thu hoạch. Nhờ các nghị định thư xuất khẩu chính ngạch được ký kết với Trung Quốc, EU và Bắc Mỹ, nông dân Việt Nam đang có nguồn thu nhập ổn định và đời sống nông thôn ngày càng thịnh vượng.",
    "referenceEn": "Good evening. Tonight on Vietnam Today, we report on the phenomenal export surge of Vietnamese tropical fruit across high-value international supermarkets. Propelled by surging global demand for buttery Ri6 durians, fragrant cát chu mangoes, and ruby red dragon fruit, fruit exports have surpassed record highs. Cooperatives in the Mekong Delta and Central Highlands rigorously adhere to GlobalGAP standards, deploying digital barcodes that trace every fruit back to its specific orchard. With new official trade protocols signed with China, the EU, and North America, Vietnamese farmers are enjoying unprecedented income security and rural prosperity.",
