    "lengthTier": "medium",
    "wordCountVi": 169,
    "textVi": "Xin chào và chào mừng bạn đến với 6 Phút Tiếng Anh của BBC Learning English! Tôi là Neil. Và tôi là Feifei. Neil này, bạn có nghĩ những người nói các ngôn ngữ khác nhau nhìn thế giới theo cách khác nhau không? Đó chính là câu hỏi lớn của thuyết tương đối ngôn ngữ! Nếu ngôn ngữ của bạn có nhiều từ riêng biệt cho các sắc thái xanh lam, liệu bạn có phân biệt chúng nhanh hơn người khác? Nhà ngôn ngữ học Lera Boroditsky đã nghiên cứu ngôn ngữ của thổ dân Úc nơi họ không dùng 'trái' hay 'phải'—mà chỉ dùng Đông, Tây, Nam, Bắc. Khả năng định hướng không gian của họ thật đáng kinh ngạc! Học tiếng Anh mang lại cho bạn một lăng kính mới để nhìn nhận nhân loại, văn học quốc tế và các cuộc đàm luận khoa học. Hãy tiếp tục mở rộng vốn từ cùng chúng tôi nhé! Ghé thăm BBC Learning English trực tuyến. Tạm biệt!",
    "referenceEn": "Hello and welcome to 6 Minute English with BBC Learning English! I'm Neil. And I'm Feifei. Neil, do you think people who speak different languages see the world differently? That is the grand question of linguistic relativity! If your language has many distinct words for shades of blue, do you distinguish them faster than others? Linguist Lera Boroditsky studied Aboriginal Australian languages where they don't use 'left' or 'right'—only North, South, East, and West. Their spatial orientation is astounding! Learning English gives you an extra lens to view humanity, international literature, and scientific discourse. Keep expanding your vocabulary with us! Visit BBC Learning English online. Goodbye!",
