    "textVi": "Xin chào và chào mừng bạn đến với 6 Phút Tiếng Anh của BBC Learning English. Tôi là Neil. Và tôi là Sam. Neil này, bạn thích lướt điện thoại hơn hay mở một cuốn sách giấy thật sự? Không gì sánh bằng mùi thơm và sức nặng của một cuốn sách hay, Sam ạ! Và các nhà khoa học xác nhận việc đọc trang sách giấy giảm mức độ căng thẳng cortisol tới 68%. Khi ta đọc truyện, não ta phản chiếu hành động của nhân vật. Kết quả chụp MRI cho thấy vỏ não vận động sáng lên khi nhân vật chạy hay nhảy! Đọc sách còn bồi đắp vốn từ chủ động và củng cố sức bền trước các thử thách học thuật phức tạp. Hãy cầm một cuốn sách lên ngay hôm nay nhé! Hẹn gặp lại quý vị vào tuần tới trong số 6 Phút Tiếng Anh tiếp theo. Tạm biệt!",
    "referenceEn": "Hello and welcome to 6 Minute English from BBC Learning English. I'm Neil. And I'm Sam. Neil, do you prefer scrolling on a phone or opening a physical paper book? There is nothing like the smell and weight of a good book, Sam! And scientists confirm that reading physical pages reduces cortisol stress levels by up to 68%. When we read stories, our brain mirrors the actions of the characters. MRI scans reveal our motor cortex lights up when characters run or jump! Reading also builds our active lexicon and strengthens stamina for complex academic challenges. Pick up a book today! Join us again next week for more 6 Minute English. Goodbye!",
