    "textVi": "Xin chào và chào mừng bạn đến với 6 Phút Tiếng Anh của BBC Learning English! Tôi là Neil. Và tôi là Dan. Hôm nay chúng ta cùng đặt câu hỏi: công thức bí mật cho một hạnh phúc chân thật và dài lâu là gì? Nhiều người tin rằng được thăng chức lớn hay mua một chiếc xe thể thao sang trọng sẽ khiến họ hạnh phúc mãi mãi. Nhưng các nhà tâm lý học chỉ ra 'vòng xoáy khoái lạc'. Chúng ta thích nghi nhanh chóng đến kinh ngạc trước những thay đổi tích cực trong cuộc sống. Chỉ trong vài tháng, sự phấn khích nhạt dần và mức cân bằng cảm xúc lại trở về như cũ. Thực hành lòng biết ơn, tình nguyện vì cộng đồng và vun đắp tình bạn sâu sắc đem lại sự mãn nguyện dài lâu cho cuộc đời.",
    "referenceEn": "Hello and welcome to 6 Minute English from BBC Learning English! I'm Neil. And I'm Dan. Today we are asking: what is the secret recipe for genuine, long-lasting happiness? Many people believe that getting a huge promotion or buying a fancy sports car will make them happy forever. But psychologists point to the 'hedonic treadmill'. We adapt remarkably quickly to positive life changes. Within months, the excitement wears off, and our emotional baseline resets. Practicing gratitude, volunteering for a community cause, and cultivating meaningful friendships generate enduring life satisfaction.",
