    "topic": "Y Tế & Sức Khỏe",
    "level": "B2",
    "lengthTier": "medium",
    "wordCountVi": 127,
    "textVi": "Nếu bạn từng cảm thấy quá tải trước một kỳ thi lớn hay bài thuyết trình, bạn biết cảm giác căng thẳng là thế nào: tim đập thình thịch, lòng bàn tay ướt mồ hôi và bụng thắt lại. Vùng dưới đồi phát tín hiệu cho tuyến thượng thận giải phóng adrenaline và cortisol, kích hoạt phản ứng chiến-hay-biến từ thời tổ tiên. Dù phản ứng này cứu sống tổ tiên khi trốn chạy thú dữ, căng thẳng mạn tính từ các hạn chót hiện đại có thể làm bào mòn hệ miễn dịch và tăng huyết áp. Tin vui là: tập luyện thể chất và thiền chánh niệm có thể đảo ngược những triệu chứng thể chất này, tái lập kiến trúc não bộ khỏe mạnh.",
    "referenceEn": "If you've ever felt overwhelmed before a big exam or presentation, you know what stress feels like: racing heartbeat, clammy palms, and a knot in your stomach. Your hypothalamus signals your adrenal glands to release adrenaline and cortisol, priming your ancestral fight-or-flight response. While this was lifesaving when fleeing predators, chronic stress from modern deadlines can wear down your immune system and elevate blood pressure. The good news: physical exercise and mindfulness meditation reverse these physical symptoms, restoring healthy brain architecture.",
