    "lengthTier": "short",
    "wordCountVi": 78,
    "textVi": "Năm 27 tuổi, tôi rời bỏ một công việc rất áp lực trong ngành tư vấn quản trị để chuyển sang một công việc còn nhiều áp lực hơn: dạy học. Trong tất cả những bối cảnh rất khác nhau ấy, một đặc tính nổi lên như là yếu tố dự báo thành công quan trọng nhất: và đó không phải là trí thông minh xã hội, ngoại hình hay chỉ số IQ. Đó là sự bền bỉ.",
    "referenceEn": "When I was 27 years old, I left a very demanding job in management consulting for a job that was even more demanding: teaching. In all those very different contexts, one characteristic emerged as a significant predictor of success: and it wasn't social intelligence, it wasn't good looks, or IQ. It was grit.",
