    "textVi": "Giấc ngủ là siêu năng lực của bạn. Hôm nay chúng ta sẽ bàn về một hệ thống duy trì sự sống mà quý vị bấy lâu nay đã xao lãng: giấc ngủ. Giấc ngủ càng ngắn, tuổi thọ của bạn càng ngắn. Sự thiếu ngủ làm thoái hóa chuỗi ADN và đẩy nhanh quá trình lão hóa sinh học.",
