    "textVi": "Tôi cần thú nhận điều này: gần hai mươi năm trước, tôi đã làm một việc mà tôi hối hận. Tôi đã đi học trường luật. Có một sự lệch pha giữa những gì khoa học biết và những gì giới kinh doanh làm. Đối với công việc thế kỷ 21, phần thưởng kiểu 'nếu-thì' thực chất làm cùn mòn tư duy sáng tạo.",
