    "lengthTier": "short",
    "wordCountVi": 65,
    "textVi": "Chúng ta đang sống trong một thế giới nơi mọi cuộc trò chuyện đều có nguy cơ biến thành tranh cãi. Nhưng năng lực đàm thoại lại là kỹ năng bị xem nhẹ nhất. Điều số một: Đừng làm nhiều việc cùng lúc. Hãy hiện diện trọn vẹn. Đừng nghĩ về bữa tối hay nhìn vào điện thoại. Hãy ở trọn trong khoảnh khắc đó.",
    "referenceEn": "We live in a world where every conversation has the potential to turn into an argument. But conversational competence is the single most overlooked skill. Number one: Don't multitask. Be present. Don't be thinking about your dinner or looking at your phone. Be in that moment.",
