    "topic": "Đời Sống & Văn Hóa",
    "level": "C1",
    "lengthTier": "short",
    "wordCountVi": 78,
    "textVi": "Tôi là một người kể chuyện. Và tôi muốn chia sẻ với quý vị một vài câu chuyện cá nhân về điều mà tôi gọi là 'mối nguy của câu chuyện đơn chiều'. Cứ miêu tả một dân tộc như một thứ, chỉ duy nhất một thứ, lặp đi lặp lại nhiều lần, và họ sẽ bị đóng khung thành đúng thứ đó. Các câu chuyện rất quan trọng. Nhiều câu chuyện đa chiều lại càng quan trọng.",
    "referenceEn": "I'm a storyteller. And I would like to tell you a few personal stories about what I like to call 'the danger of the single story.' Show a people as one thing, as only one thing, over and over again, and that is what they become. Stories matter. Many stories matter.",
