    "topic": "Giáo Dục & Trí Tuệ",
    "level": "C1",
    "lengthTier": "short",
    "wordCountVi": 81,
    "textVi": "Năm tôi lên chín tuổi, tôi tham gia trại hè lần đầu tiên. Mẹ tôi xếp cho tôi một vali đầy ắp sách, điều mà lúc bấy giờ có vẻ là một việc hoàn toàn tự nhiên. Sự thanh tịnh tĩnh lặng rất quan trọng. Và với một số người, đó là bầu không khí để họ hít thở. Xã hội phương Tây đã phát triển một thiên kiến nghiêng về người hướng ngoại khiến chúng ta phải trả giá đắt.",
    "referenceEn": "When I was nine years old, I went to summer camp for the first time. And my mother packed me a suitcase full of books, which seemed like an entirely natural thing to do. Solitude matters. And for some people, it is the air that they breathe. Western society has developed a bias toward extroversion that costs us dearly.",
