    "lengthTier": "short",
    "wordCountVi": 68,
    "textVi": "Bạn và những người bạn đồng hành đang chạy trốn khỏi một bầy thây ma trong đêm khuya. Phía trước là một cây cầu treo ọp ẹp chỉ chịu được sức nặng hai người cùng lúc. Thời gian di chuyển của từng người là 1, 2, 5 và 10 phút. Cây cầu sẽ sập sau 17 phút. Làm thế nào để đưa cả bốn người qua an toàn?",
