    "level": "B2",
    "lengthTier": "short",
    "wordCountVi": 75,
    "textVi": "Hãy tưởng tượng bạn đang dạo bước qua khu rừng tĩnh lặng và bỗng nghe thấy một giọng nói rõ ràng gọi tên mình, hay thoáng thấy bóng hình một bóng ma lướt qua. Ảo giác là những tri giác giác quan được tạo ra mà không có tác nhân vật lý bên ngoài. Chúng làm sáng tỏ cách thức mà nhận thức phần lớn là một sự kiến tạo từ bên trong nội tâm.",
