    "textVi": "Há miệng rộng, hít một hơi thật sâu và thở ra: bạn vừa ngáp rồi đấy. Và nếu ai đó ở bên kia phòng nhìn thấy bạn, nhiều khả năng họ cũng sẽ ngáp theo chỉ sau vài giây. Vì sao lại thế? Các nhà khoa học tiến hóa liên kết việc ngáp lây lan với lòng thấu cảm và sự đồng điệu xã hội. Mạng nơ-ron gương trong não ta bắt chước hành vi quan sát được một cách vô thức.",
