    "textVi": "Dưới độ sâu hơn mười nghìn mét tại rãnh Mariana, ánh sáng mặt trời hoàn toàn biến mất và áp suất nước lớn gấp hàng nghìn lần trên mặt biển. Trái với suy nghĩ trước đây rằng nơi này hoàn toàn hoang vắng, các nhà khoa học đã tìm thấy những hệ sinh thái phong phú quanh các miệng phun thủy nhiệt dưới đáy đại dương. Thay vì quang hợp, vi khuẩn tại tầng đáy sâu sử dụng hóa chất từ lòng đất để tổng hợp dinh dưỡng, nuôi sống giun ống, tôm mù và nhiều loài cá phát quang sinh học kỳ lạ.",
