    "textVi": "Sau giai đoạn tranh luận gay gắt giữa làm việc tại nhà hoàn toàn và quay lại công sở năm ngày mỗi tuần, nhiều doanh nghiệp đang tìm thấy điểm cân bằng ở mô hình kết hợp ba ngày tại văn phòng và hai ngày làm việc từ xa. Thiết kế tuần làm việc có chủ đích này giúp nhân viên tiết kiệm thời gian đi lại và giữ được sự tự chủ trong những đầu việc đòi hỏi tập trung cao độ qua giao tiếp bất đồng bộ. Vào ba ngày cố định có mặt cùng nhau, các nhóm ưu tiên hoạt động cố vấn cho nhân sự trẻ, thảo luận chiến lược và kết nối đồng nghiệp trực tiếp. Cách tổ chức linh hoạt như vậy vừa duy trì văn hóa doanh nghiệp gắn kết, vừa nâng cao hiệu suất công việc thực chất.",
    "referenceEn": "After intense debate between full-time remote work and a strict five-day office return, many companies are finding balance in a three-two hybrid schedule. This intentional workweek design saves employees commuting time while preserving autonomy for deep solo tasks managed through asynchronous communication. On the three designated anchor days in the office, teams prioritize mentoring junior staff, brainstorming strategy, and strengthening in-person collaboration. Organizing schedules this way maintains cohesive company culture while boosting measurable workplace productivity.",
