    "referenceEn": "Unlike the Apollo flights that landed near the equator, NASA's Artemis mission targets the Moon's South Pole. Inside permanently shadowed polar craters, orbiters have detected valuable water ice reserves. This local ice can provide drinking water for astronauts, breathable oxygen, and sustainable rocket propellant.",
