    "textVi": "Tại Singapore và Tokyo, các trang trại thủy canh xếp tầng trong nhà đang thay đổi cách cung ứng rau xanh đô thị. Nhờ đèn LED chuyên dụng và dòng nước tuần hoàn, mô hình này giảm tới chín mươi phần trăm lượng nước tưới. Rau sạch không thuốc trừ sâu được giao tới siêu thị chỉ vài giờ sau thu hoạch, rút ngắn quãng đường vận chuyển.",
    "referenceEn": "In Singapore and Tokyo, indoor stacked hydroponic farms are reshaping urban produce supply. Using tailored LED lighting and closed-loop water recirculation, these facilities cut irrigation water by ninety percent. Pesticide-free greens reach supermarkets within hours of harvest, dramatically shrinking food miles.",
