    "level": "B2",
    "lengthTier": "medium",
    "wordCountVi": 162,
    "textVi": "Vì sao một số người dễ dàng duy trì thói quen chạy bộ buổi sáng trong khi người khác bỏ cuộc chỉ sau vài ngày? Khoa học thần kinh chỉ ra rằng mọi thói quen đều vận hành theo vòng lặp ba bước gồm tín hiệu kích hoạt, chuỗi hành động và phần thưởng. Khi một hành vi mới bắt đầu hình thành, vỏ não trước trán phải tiêu tốn nhiều năng lượng để ra quyết định có ý thức. Tuy nhiên, nếu hành vi đó được lặp lại đều đặn cùng chất dẫn truyền thần kinh dopamine đóng vai trò củng cố, quyền điều khiển sẽ dần chuyển sang vùng hạch nền nằm sâu trong não. Lúc này, hành động diễn ra gần như tự động mà không cần nhiều nỗ lực ý chí. Hiểu rõ cơ chế sinh học này giúp người học thiết kế môi trường sống thông minh nhằm xây dựng kỷ luật cá nhân bền vững hơn.",
    "referenceEn": "Why do some people effortlessly keep up a morning running habit while others quit after just a few days? Neuroscience reveals that every habit operates through a three-step loop consisting of a cue, a routine, and a reward. When a new behavior first takes shape, the prefrontal cortex expends considerable energy making conscious decisions. However, as that action repeats consistently alongside dopamine-driven reinforcement, control gradually shifts to the basal ganglia deep inside the brain. At that stage, the routine unfolds with near automaticity and minimal willpower. Understanding this biological mechanism helps learners design smarter daily environments to build lasting personal discipline.",
