    "level": "B1",
    "lengthTier": "medium",
    "wordCountVi": 126,
    "textVi": "Trước đây, việc tìm kiếm một loại thuốc mới thường mất hơn một thập kỷ và tiêu tốn hàng tỷ đô la cho các phép thử trong phòng thí nghiệm. Ngày nay, các mô hình trí tuệ nhân tạo có thể dự đoán cấu trúc không gian ba chiều của hàng triệu loại protein chỉ trong vài ngày. Nhờ bản đồ sinh học chính xác này, nhà khoa học nhanh chóng sàng lọc được những phân tử tiềm năng có khả năng gắn kết với mục tiêu gây bệnh. Kết hợp cùng dữ liệu hệ gen của bệnh nhân, công nghệ mới rút ngắn đáng kể giai đoạn tiền lâm sàng và mở ra cơ hội điều trị hiệu quả cho nhiều căn bệnh hiếm gặp.",
    "referenceEn": "Previously, developing a new medication often took over a decade and cost billions of dollars in laboratory testing. Today, artificial intelligence models can predict the three-dimensional folding structures of millions of proteins in just days. Armed with these accurate biological blueprints, scientists rapidly screen promising candidate molecules capable of binding to disease targets. Combined with patient genomics data, this technology significantly shortens preclinical discovery and opens effective treatment pathways for rare illnesses.",
