    "lengthTier": "medium",
    "wordCountVi": 153,
    "textVi": "Cuộc đua chế tạo pin xe điện thế hệ mới đang làm nóng thị trường khoáng sản chiến lược và thúc đẩy hàng loạt liên minh công nghiệp mới giữa các hãng xe và doanh nghiệp khởi nghiệp. Hiện tại, việc khai thác lithium và cobalt vẫn tập trung ở một số khu vực địa lý nhạy cảm, làm dấy lên lo ngại về chi phí biến động cũng như điều kiện lao động tại mỏ. Để chủ động chuỗi cung ứng, nhiều nhà sản xuất đang xây dựng các siêu nhà máy pin ngay gần thị trường tiêu thụ tại châu Âu và Bắc Mỹ. Song song đó, các dây chuyền thử nghiệm pin thể rắn và pin không chứa cobalt liên tục được mở rộng công suất nhằm giảm sự phụ thuộc vào kim loại hiếm đắt đỏ, hứa hẹn hạ giá thành xe điện phổ thông trong vài năm tới.",
    "referenceEn": "The race to manufacture next-generation electric vehicle batteries is heating up strategic mineral markets and sparking new industrial alliances between automakers and startups. Currently, lithium and cobalt mining remains concentrated in a handful of sensitive regions, raising concerns over price volatility and labor standards. To secure their supply chains, manufacturers are building massive battery gigafactories close to consumer markets in Europe and North America. At the same time, pilot production lines for solid-state and cobalt-free chemistries are steadily scaling up to reduce reliance on costly rare minerals, promising more affordable electric cars over the coming years.",
