    "referenceEn": "Many people expect an inspiring weekend burst of willpower to transform their daily habits overnight, yet the brain's biological architecture follows a fundamentally different rule. Through neuroplasticity, synaptic connections between neurons continuously reorganize around the actions we repeat most consistently. Whenever a constructive habit or skill is practiced with steady daily consistency, specialized cells wrap active neural pathways in thicker layers of myelin, accelerating signal transmission until the behavior feels effortless. Conversely, underused synapses undergo pruning so the brain can reallocate energy toward active circuits. Consequently, lasting self-discipline depends less on intense short-lived motivation than on lowering friction and sustaining small, reliable repetitions each day.",
