    "wordCountVi": 194,
    "textVi": "Khi doanh số xe điện tăng nhanh trên toàn cầu, nút thắt hạ tầng không còn chỉ nằm ở số lượng trụ sạc công cộng mà chuyển sang năng lực chịu tải của mạng lưới phân phối điện đô thị. Nếu hàng nghìn chủ xe đồng loạt cắm bộ sạc siêu nhanh vào giờ cao điểm buổi tối, hệ thống máy biến áp khu dân cư rất dễ rơi vào tình trạng quá tải cục bộ. Để giải quyết bài toán này mà không phải đào đường nâng cấp toàn bộ cáp ngầm tốn kém, các công ty điện lực đang thử nghiệm công nghệ sạc hai chiều kết nối xe với lưới điện. Theo cơ chế V2G thông minh, bộ pin dung lượng lớn trên những chiếc xe đang đỗ sẽ nạp điện dư thừa vào ban đêm hoặc giữa trưa giá rẻ, rồi tự động trả ngược một phần năng lượng về lưới khi nhu cầu thành phố tăng vọt. Nhờ đó, đội xe điện giao thông không chỉ tiêu thụ điện mà còn hóa thân thành nguồn dự phòng linh hoạt giúp ổn định toàn hệ thống năng lượng quốc gia.",
    "referenceEn": "As global electric vehicle adoption accelerates, the primary infrastructure bottleneck is shifting from the number of public plugs to the capacity of urban electricity distribution grids. If thousands of drivers plug into high-power fast chargers simultaneously during evening peak hours, neighborhood transformers risk severe local overloads. To address this challenge without costly excavation to replace all underground cables, utilities are piloting bidirectional vehicle-to-grid charging technology. Under smart V2G coordination, parked vehicles absorb surplus off-peak power overnight or at midday and automatically feed stored electricity back into the grid when city demand spikes. In doing so, electric vehicle fleets transform from heavy power consumers into flexible distributed assets that stabilize national energy networks.",
