    "textVi": "Các quy định thương mại xanh mới tại châu Âu và Bắc Mỹ đang buộc doanh nghiệp xuất khẩu phải minh bạch hóa toàn bộ dấu chân carbon trong chuỗi cung ứng, kể cả lượng phát thải gián tiếp từ khâu khai thác nguyên liệu thô. Trước đây, nhiều tập đoàn lớn chỉ kiểm soát nhà máy lắp ráp cuối cùng và gần như không nắm rõ quy trình môi trường của các nhà cung cấp cấp hai hay cấp ba. Ngày nay, công nghệ hộ chiếu sản phẩm kỹ thuật số cho phép truy xuất nguồn gốc từng lô hàng từ mỏ khoáng sản, xưởng dệt nhuộm cho tới cảng vận tải biển sử dụng nhiên liệu xanh. Dù việc kiểm toán dữ liệu phát thải đòi hỏi hệ thống đo lường phức tạp và chi phí tuân thủ không nhỏ, các chuyên gia thương mại khẳng định minh bạch chuỗi cung ứng đang trở thành giấy thông hành bắt buộc để giữ vững thị phần quốc tế.",
    "referenceEn": "New green trade regulations in Europe and North America are compelling exporters to disclose the full carbon footprint across their supply chains, including indirect emissions from raw material extraction. Historically, major corporations audited only final assembly plants while remaining largely blind to environmental practices among second- and third-tier suppliers. Today, digital product passports enable end-to-end traceability, tracking each shipment from mineral mines and textile dye houses to container vessels powered by green shipping fuels. Although verifying emissions data demands rigorous auditing infrastructure and substantial compliance spending, trade analysts emphasize that supply chain transparency has become an indispensable passport for retaining global market access.",
