    "textVi": "Trí tuệ nhân tạo đang đóng vai trò con dao hai lưỡi trên mặt trận an ninh mạng hiện đại. Về phía tấn công, tội phạm mạng tận dụng công cụ tạo sinh để tự động hóa hàng loạt chiến dịch lừa đảo nhắm mục tiêu tinh vi, thậm chí giả mạo giọng nói và hình ảnh deepfake của lãnh đạo doanh nghiệp để chiếm đoạt tiền hoặc thông tin mật. Đáp lại, các đội ngũ phòng thủ cũng triển khai hệ thống giám sát thông minh có khả năng phân tích hàng tỷ gói dữ liệu mỗi giây. Nhờ thuật toán phát hiện bất thường theo thời gian thực, phần mềm bảo mật nhanh chóng khoanh vùng hành vi truy cập trái phép và cô lập máy chủ bị xâm nhập trước khi thiệt hại lan rộng.",
    "referenceEn": "Artificial intelligence is acting as a double-edged sword on the modern cybersecurity battlefield. On the offensive side, cybercriminals harness generative tools to launch automated spear-phishing campaigns and even fabricate convincing deepfake voice or video calls impersonating executives to steal funds or credentials. In response, defense teams deploy AI-driven monitoring platforms capable of inspecting billions of data packets every second. Through real-time anomaly detection, security software swiftly isolates suspicious access behavior and quarantines compromised servers before damage spreads.",
