    "lengthTier": "long",
    "wordCountVi": 195,
    "textVi": "Thay vì chỉ kêu gọi người dân tự giác phân loại rác, nhiều quốc gia châu Âu đã ban hành luật trách nhiệm mở rộng của nhà sản xuất nhằm giải quyết tận gốc bài toán rác thải bao bì. Theo khung chính sách này, các hãng đồ uống và bán lẻ phải chịu trách nhiệm tài chính trực tiếp cho việc thu gom và tái chế vỏ chai nhựa mà họ đưa ra thị trường. Kết hợp cùng hệ thống đặt cọc hoàn trả kỹ thuật số tại siêu thị, người tiêu dùng được hoàn lại một khoản tiền nhỏ mỗi khi đưa chai PET rỗng vào máy thu hồi tự động. Cơ chế khuyến khích kinh tế rõ ràng này đã giúp tỷ lệ thu gom chai nhựa tại nhiều nước vượt ngưỡng tám mươi lăm phần trăm, đồng thời tạo nguồn nguyên liệu đầu vào sạch cho các nhà máy phân loại hiện đại. Kinh nghiệm thực tiễn cho thấy sự kết hợp giữa quy định pháp lý chặt chẽ và tiện ích hoàn trả thuận lợi mang lại hiệu quả vượt trội so với các chiến dịch tuyên truyền đơn thuần.",
    "referenceEn": "Rather than relying solely on voluntary household sorting, many European nations have enacted extended producer responsibility laws to tackle packaging waste at its source. Under this policy framework, beverage makers and retailers bear direct financial accountability for collecting and recycling the plastic containers they place on the market. Paired with digital deposit return schemes in supermarkets, consumers receive a small cash refund or credit whenever they feed empty PET bottles into automated reverse-vending machines. This clear economic incentive has pushed plastic bottle collection rates past eighty-five percent across several countries while supplying clean feedstock for modern sorting facilities. Practical experience demonstrates that combining binding regulation with convenient return infrastructure outperforms awareness campaigns alone.",
    "keywords": [
      "deposit return",
      "extended producer",
      "policy",
      "sorting",
      "incentive"
    ]
