    "lengthTier": "long",
    "wordCountVi": 203,
    "textVi": "Sau nhiều thập kỷ thống trị thị trường năng lượng sạch, tế bào quang điện silicon truyền thống đang dần chạm tới giới hạn vật lý về khả năng chuyển hóa ánh sáng mặt trời thành điện năng. Để vượt qua rào cản hiệu suất khoảng hai mươi sáu phần trăm, các nhà vật lý vật liệu đã kết hợp lớp phủ tinh thể perovskite siêu mỏng lên trên nền pin silicon nhằm tạo ra cấu trúc pin song song hai lớp. Thiết kế thông minh này cho phép lớp perovskite phía trên hấp thụ mạnh tia sáng xanh năng lượng cao, trong khi lớp silicon bên dưới thu nhận phần ánh sáng đỏ và hồng ngoại còn lại. Nhờ tận dụng dải quang phổ rộng hơn, các mẫu pin tandem thế hệ mới đã phá vỡ cột mốc hiệu suất ba mươi phần trăm trong phòng thí nghiệm, đánh dấu bước đột phá quan trọng của ngành điện mặt trời. Hiện tại, trọng tâm nghiên cứu đang dồn vào việc cải thiện lớp màng bảo vệ để giúp tinh thể perovskite chống chịu tốt trước độ ẩm, tia cực tím và chu kỳ nhiệt ngoài trời suốt hàng chục năm vận hành.",
    "referenceEn": "After decades of dominating clean energy markets, conventional silicon solar cells are gradually approaching their physical ceiling for converting sunlight into electricity. To surpass the roughly twenty-six percent efficiency limit, materials physicists have layered ultra-thin perovskite crystals atop standard silicon wafers to build tandem solar architectures. This clever two-tier design lets the upper perovskite film capture high-energy blue wavelengths while the underlying silicon cell absorbs remaining red and infrared light. By harvesting a broader slice of the solar spectrum, next-generation tandem prototypes have broken the thirty percent efficiency barrier in laboratory tests, marking a major breakthrough for solar engineering. Current research now concentrates on encapsulating perovskite layers against moisture, ultraviolet exposure, and outdoor thermal stress to guarantee multi-decade durability.",
