    "textVi": "Ít ai ngờ rằng những vực thẳm lạnh giá dưới đáy đại dương lại đóng vai trò là bể chứa carbon lớn nhất hành tinh. Hằng ngày, hàng triệu tấn mảnh vụn hữu cơ từ tầng nước mặt lắng chìm xuống như tuyết biển, cùng với xác của những loài cá voi lớn tạo thành nguồn dinh dưỡng quý giá dưới đáy sâu. Khi lắng đọng vào lớp bùn trầm tích, lượng carbon này được cô lập an toàn suốt hàng nghìn năm, góp phần điều hòa khí hậu Trái Đất.",
    "referenceEn": "Few realize that frigid deep-ocean trenches serve as Earth's largest natural carbon sink. Every day, millions of tons of organic marine snow drift downward from sunlit surface waters, alongside giant whale falls that nourish deep-sea ecosystems. Once buried inside seafloor sediment layers, this carbon remains locked away in long-term sequestration for millennia, helping regulate the global climate.",
