    "textVi": "Để ứng phó với bão lớn, đình công cảng biển hay biến động nhu cầu bất ngờ, các tập đoàn bán lẻ lớn đang xây dựng bản sao số cho toàn bộ mạng lưới hậu cần của mình. Mô hình mô phỏng thời gian thực này kết nối dữ liệu từ nhà máy sản xuất, tàu vận tải và hệ thống robot tự động trong kho bãi để chạy hàng nghìn kịch bản dự báo mỗi giờ. Nhờ năng lực phân tích dự đoán chính xác, doanh nghiệp có thể phát hiện nguy cơ thiếu hụt hàng tồn kho trước nhiều tuần và chủ động điều chuyển nguồn hàng trước khi kệ siêu thị bị trống.",
    "referenceEn": "To withstand severe storms, port strikes, or sudden demand swings, major retail corporations are constructing a digital twin of their entire logistics network. This real-time virtual simulation links live feeds from factories, cargo ships, and automated warehouse robotics to run thousands of stress scenarios every hour. Powered by predictive analytics, supply chain managers can spot potential inventory shortages weeks in advance and reroute stock long before store shelves go empty.",
