    "textVi": "Các căn cứ Mặt Trăng đóng vai trò bãi thử nghiệm thiết yếu trước khi nhân loại bay tới sao Hỏa. Cách Trái Đất vài ngày hành trình, phi hành đoàn có thể kiểm tra hệ thống hỗ trợ sự sống khép kín, tái chế nước thải và trồng rau thủy canh dài ngày. Kinh nghiệm từ môi trường mô phỏng này sẽ bảo đảm an toàn cho sứ mệnh hành tinh đỏ.",
    "referenceEn": "Lunar bases serve as a vital proving ground before humanity journeys to Mars. Just days from Earth, crews can test closed-loop life support systems, wastewater recycling, and long-duration hydroponics. Insights from this lunar analogue will keep astronauts safe on Mars missions.",
