    "textVi": "Không cần công nghệ đắt tiền, những khu vườn cộng đồng và điểm ủ phân hữu cơ đô thị đang làm thay đổi diện mạo của nhiều khu dân cư thiếu hụt thực phẩm tươi. Người dân cùng nhau cải tạo các bãi đất trống bê tông thành luống rau sạch, trồng thêm hoa thu hút ong bướm thụ phấn và gia tăng đa dạng sinh học. Những khoảng xanh mộc mạc này còn trở thành nơi gắn kết hàng xóm thuộc nhiều thế hệ.",
