    "textVi": "Dù máy tính lượng tử quy mô lớn chưa hoàn thiện, giới an ninh mạng đã cảnh báo về chiến thuật thu thập dữ liệu mã hóa hôm nay để chờ giải mã trong tương lai. Trước mối đe dọa này đối với hồ sơ ngân hàng và bí mật quốc gia, các viện tiêu chuẩn công nghệ đang khẩn trương ban hành những thuật toán mật mã hậu lượng tử mới. Quá trình nâng cấp và chuyển đổi hạ tầng mã hóa đòi hỏi các tổ chức phải lên kế hoạch từ sớm để tránh bị động.",
    "referenceEn": "Although large-scale quantum computers are not yet fully built, cybersecurity agencies warn against attackers harvesting encrypted data today to decrypt it later. To protect banking systems and government networks from this looming risk, standards bodies are finalizing resilient post-quantum cryptography algorithms. Planning an orderly encryption migration now ensures critical institutions will not be caught off guard.",
