    "referenceEn": "Because the old square is undergoing sidewalk repaving, the weekend organic farmers market will temporarily move to the north park lawn throughout May. Produce and wildflower honey stalls line the main walkway for easier access by elderly shoppers. Visitors bringing reusable cloth bags still receive regular discount vouchers.",
