    "textVi": "Khi bước vào vùng đệm của khu bảo tồn chim nước, quý khách vui lòng chuyển điện thoại sang chế độ im lặng và tắt đèn flash máy ảnh. Tiếng ồn đột ngột có thể khiến chim mẹ hoảng sợ bỏ tổ trong mùa sinh sản. Ống nhòm công suất cao được lắp sẵn tại ba đài quan sát bằng gỗ dọc bờ đầm lầy.",
