    "level": "C1",
    "lengthTier": "medium",
    "wordCountVi": 141,
    "textVi": "— An ơi, mẫu nước thu được ở cửa sông tuần trước có vẻ bị nhiễu số liệu vì lẫn nhiều sợi vải tổng hợp từ áo phao của nhóm mình. — Mình cũng nghi ngờ điều đó khi xem lại hình ảnh dưới kính hiển vi sáng nay; tỷ lệ sợi xanh dương cao bất thường ở cả ba điểm đo. — Thế thì lần ra khơi tới chúng ta bắt buộc phải mặc trang phục vải bông tự nhiên và dùng bình thủy tinh thay cho can nhựa thông thường. — Chuẩn luôn, ngoài ra mình đề xuất lọc mẫu ngay tại boong tàu rồi niêm phong bằng giấy bạc để tránh bụi không khí rơi vào. Làm kỹ ngay từ khâu thực địa sẽ giúp bài nghiên cứu tránh bị hội đồng phản biện bắt lỗi quy trình.",
    "referenceEn": "\"An, last week's estuary water samples look skewed because synthetic fibers from our own life vests contaminated them.\" \"I suspected that too under the microscope this morning; blue fiber counts were unusually high across all three stations.\" \"Then on our next boat trip we must wear natural cotton clothing and switch from plastic jugs to glass flasks.\" \"Agreed—plus I suggest filtering samples right on deck and sealing them with foil to block airborne dust. Tightening fieldwork controls now will keep peer reviewers from faulting our methodology.\"",
