    "level": "B1",
    "lengthTier": "medium",
    "wordCountVi": 118,
    "textVi": "— Nha khoa Minh Tâm xin nghe ạ. — Chào em, anh là Nam có lịch lấy cao răng vào lúc mười giờ sáng thứ Sáu tuần này, nhưng công ty vừa điều anh đi công tác đột xuất ở Cần Thơ. — Dạ không sao anh Nam ơi, anh muốn dời sang tuần sau vào khung giờ nào tiện nhất ạ? — Thứ Ba tuần tới khoảng năm giờ chiều sau giờ làm có còn trống không em? — Dạ bác sĩ Linh có lịch trống lúc năm giờ mười lăm thứ Ba anh nhé. Em đã cập nhật lại trên hệ thống và gửi tin nhắn xác nhận qua số điện thoại của anh rồi ạ.",
    "referenceEn": "\"Minh Tam Dental Clinic, how can I assist you?\" \"Hi, this is Nam—I have a cleaning appointment at ten a.m. this Friday, but my company just sent me on an unexpected business trip to Can Tho.\" \"No problem at all, Mr. Nam; what time next week works best to reschedule?\" \"Does next Tuesday around five p.m. after office hours happen to be open?\" \"Dr. Linh has an opening at five-fifteen on Tuesday. I have updated your booking and sent a confirmation text to your phone.\"",
