    "id": "tb_media_extra_031",
    "title": "Gọi bộ phận kỹ thuật xử lý lỗi kết nối máy chiếu",
    "titleEn": "Troubleshooting a Classroom Projector Over the Phone",
    "sourceGroup": "video",
    "sourceLabel": "Listening Practice",
    "unitId": null,
    "unitNumber": null,
    "topic": "IT Helpdesk Troubleshooting",
    "level": "B1",
    "lengthTier": "medium",
    "wordCountVi": 125,
    "textVi": "— Phòng hỗ trợ kỹ thuật xin nghe, tôi là Hùng. — Chào anh Hùng, tôi đang ở phòng hội thảo A204 mà máy chiếu chỉ hiện màn hình xanh dù đã cắm dây HDMI vào máy tính xách tay rồi. — Chị thử nhìn xem biểu tượng đầu vào trên điều khiển từ xa đang để ở cổng HDMI 1 hay HDMI 2 nhé. — À, nó đang kẹt ở cổng VGA cũ, để tôi bấm chuyển lại... Ồ, hình ảnh lên rồi nhưng vẫn chưa có tiếng qua loa trần ạ. — Vậy chị vào phần cài đặt âm thanh trên máy tính rồi chọn thiết bị xuất là hệ thống loa phòng họp thay vì loa máy tính là nghe rõ ngay.",
    "referenceEn": "\"IT Helpdesk speaking, this is Hung.\" \"Hi Hung, I am in seminar room A204 and the projector shows only a blue screen even though my laptop HDMI cable is plugged in.\" \"Could you check whether the remote input source is set to HDMI 1 or HDMI 2?\" \"Oh, it was stuck on the old VGA port—let me switch it... Great, the slides appeared, though there is no sound from the ceiling speakers.\" \"In that case, open your laptop sound settings and switch the output device from internal speakers to the room audio system.\"",
