    "level": "B2",
    "lengthTier": "medium",
    "wordCountVi": 156,
    "textVi": "Tại Milan, Singapore và nhiều đô thị chật chội khác, kiến trúc sư đang đưa hàng trăm cây bụi và cây gỗ nhỏ lên ban công các tòa chung cư cao tầng. Những mặt tiền phủ kín màu xanh này không chỉ làm dịu mắt người qua đường mà còn hấp thụ bụi mịn và giảm nhiệt độ bức xạ vào mùa hè. Nhờ lớp lá cây che chắn ánh nắng trực tiếp, cư dân bên trong có thể cắt giảm đáng kể công suất máy điều hòa trong những tháng nóng đỉnh điểm. Tuy nhiên, trồng cây trên độ cao hàng chục mét đòi hỏi hệ thống tưới nhỏ giọt thông minh và đội ngũ cắt tỉa chuyên nghiệp để tránh gãy đổ khi bão lớn. Dù chi phí bảo trì ban đầu không rẻ, giá trị sinh thái và sức khỏe tinh thần mang lại khiến mô hình này ngày càng được ưa chuộng.",
    "referenceEn": "In Milan, Singapore, and other dense cities, architects are planting hundreds of shrubs and small trees across high-rise apartment balconies. These leafy facades do more than soften concrete skylines; they trap fine dust and absorb intense summer heat. With foliage shading windows from direct glare, residents inside cut air-conditioning use noticeably during heatwaves. Still, cultivating trees dozens of meters above street level demands smart drip-irrigation networks and trained arborists to prevent storm damage. Despite higher upfront upkeep, the ecological payoff and mental calm continue winning over city planners.",
