    "lengthTier": "medium",
    "wordCountVi": 171,
    "textVi": "Công nghệ trí tuệ nhân tạo ngày nay có thể ghép khuôn mặt và mô phỏng giọng nói của bất kỳ nhân vật công chúng nào giống thật đến mức khó phân biệt bằng mắt thường. Những đoạn video giả mạo tinh vi này từng được dùng để phát tán phát ngôn bịa đặt, thao túng thị trường tài chính hoặc lừa đảo chuyển tiền qua cuộc gọi trực tuyến. Trong tập phát sóng tuần này, chuyên gia an ninh mạng khuyên người xem chú ý tới những chi tiết bất thường như nhịp chớp mắt cứng nhắc, viền cổ áo nhòe khi quay đầu hoặc ánh sáng phản chiếu không khớp trên mắt. Tuy nhiên, khi công nghệ tạo sinh ngày càng hoàn thiện, mắt thường sớm muộn cũng trở nên bất lực trước các bản dựng công phu. Do đó, thói quen kiểm tra nguồn phát hành gốc và đặt câu hỏi hoài nghi lành mạnh trước mọi tin nóng gây sốc mới là lá chắn bền vững nhất.",
    "referenceEn": "Artificial intelligence can now swap faces and clone voices of public figures with startling realism that fools casual viewers. Sophisticated deepfake clips have already been used to fabricate speeches, rattle financial markets, and stage live video-call scams. In this week's episode, cybersecurity analysts advise watching for subtle flaws like stiff blinking patterns, blurred collar edges during head turns, or mismatched light reflections on irises. Yet as generative software improves, naked eyes will inevitably fall behind polished fakes. Cultivating the habit of verifying primary sources and applying healthy skepticism toward shocking viral clips remains our strongest defense.",
