    "level": "B2",
    "lengthTier": "medium",
    "wordCountVi": 157,
    "textVi": "Khi chiếc điện thoại hay máy hút bụi bị hỏng một viên pin nhỏ, nhiều người tiêu dùng đành vứt bỏ cả máy vì chi phí sửa chữa tại hãng gần bằng mua thiết bị mới. Tình trạng thiết kế gắn keo kín mít và sử dụng ốc vít độc quyền đang biến hàng triệu tấn đồ điện tử còn dùng tốt thành rác thải công nghệ mỗi năm. Phong trào đòi quyền tự sửa chữa tại châu Âu và Bắc Mỹ đang thúc đẩy luật buộc nhà sản xuất cung cấp linh kiện thay thế cùng tài liệu hướng dẫn minh bạch cho thợ độc lập. Các hãng công nghệ từng phản đối vì lo ngại mất an toàn kỹ thuật và lộ bí mật thiết kế phần cứng. Tuy nhiên, áp lực bảo vệ tài nguyên hiếm đang buộc ngành điện tử hướng tới thiết kế dạng mô-đun dễ tháo lắp và bền bỉ hơn.",
    "referenceEn": "When a smartphone or vacuum fails over a single worn battery, consumers often discard the entire machine because official repairs cost nearly as much as buying new. Heavy glue seals and proprietary screws turn millions of tons of fixable gadgets into electronic waste every year. The Right to Repair movement across Europe and North America pushes laws requiring manufacturers to supply spare parts and clear repair manuals to independent technicians. Tech firms pushed back, citing safety hazards and hardware trade secrets. Yet mounting pressure to conserve rare minerals is steering electronics toward modular, longer-lasting designs.",
