    "referenceEn": "Sand and window glass share the exact same silicon dioxide building blocks, yet sand looks opaque while glass lets you see right through. The secret lies in how much energy the electrons inside the material require. Visible light photons lack enough energy to push glass electrons up an energy level, so light passes straight through unabsorbed.",
