    "referenceEn": "In less than a second, an octopus can shift its skin from sandy brown to vivid coral stripes. Beneath its surface lie millions of tiny pigment sacs called chromatophores controlled directly by its nervous system. By snapping muscles open or shut around those sacs, it vanishes instantly from predators.",
