    "textVi": "Khi bạn cắn một miếng ớt cay, lưỡi bạn thực chất không hề bị bỏng hay tăng nhiệt độ. Hợp chất capsaicin trong quả ớt đánh lừa các thụ thể cảm giác đau trên lưỡi vốn chỉ kích hoạt khi chạm nước sôi. Não bộ lập tức tưởng miệng đang gặp nguy hiểm nên phát lệnh đổ mồ hôi và tiết endorphin để làm dịu cơn đau giả.",
    "referenceEn": "When you bite into a chili pepper, your tongue does not actually heat up or suffer a burn. A compound called capsaicin tricks pain receptors on your tongue normally triggered only by scalding temperatures. Believing your mouth faces real danger, your brain triggers sweating and releases endorphins to soothe the false alarm.",
