    "textVi": "Chúng ta thường tin rằng càng nhiều lựa chọn thì càng dễ tìm thấy món đồ hoàn hảo nhất. Thế nhưng thí nghiệm tại siêu thị cho thấy khách hàng đứng trước quầy mứt có hai mươi bốn vị lại mua ít hơn hẳn nhóm chỉ có sáu vị. Quá nhiều phương án khiến não bộ kiệt sức vì so sánh và dễ hối tiếc sau khi quyết định.",
