    "textVi": "Nghệ thuật gấp giấy truyền thống Nhật Bản không chỉ tạo ra hạc giấy trang trí mà còn giải quyết những bài toán kỹ thuật hóc búa ngoài vũ trụ. Các kỹ sư NASA áp dụng quy tắc nếp gấp hình học để thu gọn những tấm pin mặt trời khổng lồ vào khoang tên lửa chật hẹp. Khi lên quỹ đạo, toàn bộ cấu trúc tự mở bung mượt mà chỉ bằng một động tác kéo nhẹ.",
