    "level": "B1",
    "lengthTier": "short",
    "wordCountVi": 74,
    "textVi": "Nhiều người có thói quen tự mua thuốc kháng sinh ngay khi bị sổ mũi hay ho do cảm lạnh. Thực tế, kháng sinh chỉ phá hủy thành tế bào hoặc bộ máy nhân đôi của vi khuẩn, trong khi virus cúm lại có cấu trúc hoàn toàn khác và ẩn nấp bên trong tế bào người. Lạm dụng kháng sinh không chữa khỏi cảm mà còn tạo ra siêu vi khuẩn kháng thuốc.",
    "referenceEn": "Many people reach automatically for antibiotics at the first sign of a runny nose or cough. Yet antibiotics target bacterial cell walls and machinery, whereas cold viruses lack those structures and hide inside our own cells. Overusing antibiotics never cures a cold; instead, it breeds dangerous drug-resistant superbugs.",
