    "textVi": "Hầu hết các chất lỏng đều co lại và đặc hơn khi đóng băng, nhưng nước lại là ngoại lệ kỳ diệu của tự nhiên. Khi đóng thành đá, các phân tử nước liên kết theo mạng tinh thể lục giác có nhiều khoảng trống khiến băng nhẹ hơn nước lỏng. Nhờ lớp băng nổi cách nhiệt trên mặt hồ mùa đông, cá và thủy sinh bên dưới vẫn sống sót chờ xuân sang.",
    "referenceEn": "Most liquids shrink and grow denser when frozen, yet water breaks that rule in a life-saving way. As water freezes, hydrogen bonds lock molecules into an open hexagonal crystal lattice that makes ice less dense than liquid water. That floating ice sheet insulates lakes below, letting fish survive harsh winters.",
