    "id": "tb_media_extra_074",
    "title": "TED-Ed: Hiện Tượng Cộng Hưởng Và Bài Học Từ Cây Cầu Tacoma",
    "titleEn": "TED-Ed: Resonance and the Tacoma Narrows Bridge Collapse",
    "sourceGroup": "video",
