    "textVi": "Đối mặt với tình trạng dân số già hóa nhanh và văn hóa làm thêm giờ kéo dài nhiều thập kỷ, nhiều đô thị Nhật Bản cùng hàng chục công ty công nghệ đang thử nghiệm tuần làm việc bốn ngày. Nhân viên có thể nghỉ thêm ngày thứ Sáu hoặc thứ Tư mà vẫn giữ nguyên lương cơ bản nếu đạt đủ chỉ tiêu năng suất tuần. Khảo sát ban đầu tại một tập đoàn tài chính cho thấy đơn ứng tuyển của lao động trẻ tăng bốn mươi phần trăm và tỷ lệ nghỉ việc vì kiệt sức giảm rõ rệt. Tuy nhiên, doanh nghiệp sản xuất nhỏ lo ngại việc rút ngắn ngày chạy dây chuyền sẽ đội chi phí nhân công theo ca. Chuyên gia nhận định mô hình này đòi hỏi cắt bỏ cuộc họp rườm rà chứ không chỉ giảm giờ làm.",
    "referenceEn": "Confronting a rapidly aging workforce and decades of grueling overtime, Japanese municipalities and dozens of tech firms are piloting a four-day workweek. Staff can take Fridays or Wednesdays off at full base pay provided weekly productivity targets are met. Early data at a financial group showed young applications surging forty percent while burnout turnover fell sharply. Smaller manufacturers, however, warn that trimming assembly-line operating days risks inflating shift costs. Analysts note that making shorter weeks viable requires cutting bloated meetings rather than merely compressing tasks.",
