    "wordCountVi": 160,
    "textVi": "Những người yêu thích sô-cô-la trên toàn cầu đang cảm nhận tác động trực tiếp của biến đổi khí hậu ngay trên kệ hàng siêu thị năm nay. Tại Bờ Biển Ngà và Ghana—hai quốc gia cung ứng hơn sáu mươi phần trăm sản lượng ca cao thế giới—chuỗi mưa lớn bất thường xen kẽ đợt gió khô nóng đã làm lây lan bệnh nấm thối quả trên diện rộng. Sản lượng thu hoạch sụt giảm mạnh đẩy giá ca cao kỳ hạn trên sàn giao dịch London và New York tăng gấp đôi chỉ trong vòng mười hai tháng. Trước áp lực chi phí nguyên liệu, nhiều hãng bánh kẹo buộc phải thu nhỏ trọng lượng thanh kẹo hoặc điều chỉnh tăng giá bán lẻ. Về dài hạn, các tổ chức nông nghiệp đang hỗ trợ nông dân Tây Phi trồng cây che bóng xen canh để bảo vệ vườn ca cao trước những mùa khô khắc nghiệt hơn.",
    "referenceEn": "Chocolate lovers worldwide are feeling climate disruption directly on supermarket shelves this year. Across Ivory Coast and Ghana—which supply over sixty percent of global cocoa—unusual torrential rains followed by scorching dry winds spread black-pod fungal disease across plantations. Plunging harvests drove cocoa futures in London and New York to double within twelve months. Squeezed by raw ingredient costs, major confectioners have either shrunk bar weights or raised retail prices. Longer term, agricultural agencies are helping West African smallholders plant shade trees alongside cocoa to shield orchards from harsher droughts.",
