    "textVi": "Thay vì chờ đợi đường dây điện quốc gia tốn kém kéo dài hàng trăm cây số qua vùng thảo nguyên thưa dân, hàng loạt ngôi làng tại Kenya đã tự vận hành các lưới điện mặt trời độc lập quy mô nhỏ. Tại mỗi cụm dân cư, một trạm pin mặt trời kết hợp ắc-quy lithium cung cấp điện ổn định cho máy xay ngũ cốc, tủ lạnh bảo quản vắc-xin và đèn học buổi tối cho học sinh. Người dân thanh toán tiền điện theo mức tiêu thụ thực tế ngay trên điện thoại di động mà không cần hóa đơn giấy rườm rà. Nhờ có điện sạch ổn định thay thế đèn dầu hỏa độc hại, thu nhập của các xưởng may và hộ kinh doanh nhỏ trong làng tăng gần gấp đôi chỉ sau một năm. Thành công thực tế này đang được nhiều quốc gia châu Phi khác học hỏi để xóa vùng trắng năng lượng.",
    "referenceEn": "Instead of waiting years for costly national power lines to stretch across sparsely populated savannas, dozens of rural Kenyan villages now run independent solar microgrids. In each settlement, a shared solar array paired with lithium battery banks delivers steady electricity for grain mills, vaccine refrigerators, and evening study lamps. Residents pay only for the power they consume via mobile money without messy paper billing. Replacing smoky kerosene lamps with clean power helped village tailors and small shops nearly double their earnings within one year. Neighboring African nations are closely studying this grassroots model to close rural energy gaps.",
