    "textVi": "Ủy ban Di sản Thế giới vừa cảnh báo gần một phần tư di tích ven biển từ Địa Trung Hải đến Nam Á đang đối mặt nguy cơ hư hại nặng vào cuối thế kỷ này. Từ pháo đài đá cổ ở Bắc Phi đến phố thương cảng lịch sử vùng Caribe, triều cường dữ dội và bão nhiệt đới thường xuyên đang ăn mòn lớp nền đá vôi tồn tại hàng trăm năm. Ngân sách eo hẹp buộc các nhà quản lý chọn lựa giữa xây đê chắn sóng tốn kém hoặc quét laser ba chiều lưu trữ trước khi di tích biến mất. Giới chuyên gia nhấn mạnh bảo vệ di sản không thể tách rời mục tiêu giảm phát thải toàn cầu. Phục hồi rừng ngập mặn kết hợp tường chắn mềm đang mang lại hy vọng cho nhiều vùng trũng.",
