    "level": "C1",
    "lengthTier": "medium",
    "wordCountVi": 163,
    "textVi": "Ít người tiêu dùng biết rằng việc sản xuất một con chip xử lý điện thoại tiên tiến đòi hỏi hàng nghìn lít nước siêu tinh khiết để rửa sạch từng phiến silicon qua hàng trăm công đoạn. Khi các tổ hợp bán dẫn mới liên tục mọc lên ở Arizona, Nhật Bản và châu Âu, áp lực tranh chấp nguồn nước ngọt với khu dân cư và nông nghiệp địa phương trở thành bài toán nan giải. Để giữ giấy phép mở rộng dây chuyền, các nhà sản xuất hàng đầu đang đầu tư hệ thống lọc màng kín cho phép tái sử dụng tới tám mươi lăm phần trăm lượng nước thải công nghiệp. Nước sau khi thu hồi được tách kim loại nặng rồi đưa ngược lại vòng tuần hoàn sản xuất hoặc tưới cây quanh khu công nghiệp. Giải pháp kỹ thuật tốn kém này đang dần trở thành tiêu chuẩn bắt buộc của ngành điện tử toàn cầu.",
    "referenceEn": "Few consumers realize that fabricating a single advanced smartphone processor requires thousands of liters of ultrapure water to rinse silicon wafers across hundreds of steps. As new semiconductor complexes rise across Arizona, Japan, and Europe, competition for freshwater against nearby towns and farms has grown acute. To secure expansion permits, leading chipmakers are investing in closed-loop membrane plants that reclaim up to eighty-five percent of industrial wastewater. Recovered water is stripped of heavy metals before returning to factory loops or irrigating industrial-park greenery. Though capital-intensive, strict water circularity is rapidly becoming mandatory across global electronics manufacturing.",
