    "textVi": "Từ sáng sớm, các nhà ga trên cao dọc trục Xa lộ Hà Nội đã nhộn nhịp sinh viên và nhân viên văn phòng quẹt thẻ lên tàu điện đô thị. Hành trình từ khu Đông vào trung tâm Bến Thành nay chỉ mất chưa đầy ba mươi phút êm ái, không còn cảnh kẹt xe nắng gắt. Sự xuất hiện của tuyến metro đầu tiên mở ra thói quen di chuyển công cộng văn minh.",
    "referenceEn": "Since early morning, elevated stations along Hanoi Highway bustle with students and office workers tapping cards onto urban trains. Traveling from the eastern suburbs into Ben Thanh downtown now takes under thirty smooth minutes, free from scorching gridlock. The arrival of the city's first metro line is cultivating cleaner public transit habits.",
