    "textVi": "Tại ngôi làng nhỏ ven sông Đuống, các nghệ nhân vẫn kiên trì dùng giấy dó phủ điệp óng ánh và màu sắc chiết xuất từ hoa hòe, than tre để in từng bức tranh dân gian. Mỗi bản khắc gỗ thị cổ truyền đòi hỏi đôi tay khéo léo hàng tuần liền mới hoàn thành nét chạm tinh xảo. Nhờ lớp học trải nghiệm cho du khách trẻ, di sản mộc bản này đang tìm thấy sức sống mới.",
    "referenceEn": "In a quiet village beside the Duong River, artisans still use seashell-coated mulberry paper and natural pigments from pagoda flowers and bamboo charcoal to press folk prints. Carving each traditional woodblock takes weeks of patient handcraft for crisp detail. Through hands-on workshops for young visitors, this woodcut heritage is gaining fresh vitality.",
