    "textVi": "Đi dạo một vòng chợ dân sinh tại Hà Nội hay Đà Nẵng hôm nay, du khách dễ dàng bắt gặp những tấm bảng mã QR đặt gọn gàng ngay bên rổ rau tươi và xe trà đá. Chỉ với vài giây quét điện thoại, tiểu thương nhận tiền tức thì mà không cần lo lắng chuyện thiếu tiền lẻ thối lại. Làn sóng tài chính số đang giúp kinh doanh nhỏ lẻ minh bạch và tiện lợi hơn.",
    "referenceEn": "Strolling through any neighborhood wet market in Hanoi or Da Nang today, visitors immediately spot neat QR code plaques perched beside fresh greens and iced-tea carts. With one quick phone scan, small vendors receive instant transfers without fumbling for small change. Vietnam's digital finance wave is making micro-businesses faster and far more convenient.",
