    "textVi": "Nép mình yên ả dưới tán cây xanh bên phố 19 tháng 12, Phố Sách Hà Nội trở thành điểm hẹn quen thuộc của các gia đình và bạn trẻ mỗi cuối tuần. Ngoài những gian hàng trưng bày sách văn học và lịch sử, nơi đây thường xuyên tổ chức tọa đàm cùng dịch giả và góc trao đổi sách cũ miễn phí. Không gian văn hóa nhỏ xinh ấy nuôi dưỡng tình yêu đọc sách giữa đô thị hối hả.",
    "referenceEn": "Tucked peacefully beneath leafy shade on December 19 Street, Hanoi Book Street has become a cherished weekend retreat for families and young readers. Alongside stalls showcasing literature and history, the lane hosts regular translator talks and free used-book swap corners. This cozy cultural pocket nurtures quiet reading habits amid a bustling capital.",
