    "lengthTier": "medium",
    "wordCountVi": 165,
    "textVi": "Cách trung tâm kinh thành Huế chỉ mười lăm phút chạy xe, làng hương Thủy Xuân rực rỡ sắc đỏ, vàng, tím của hàng nghìn bó chân hương phơi nắng dọc hai bên đường. Nghề làm hương trầm thủ công tại đây đã truyền qua nhiều thế hệ, sử dụng bột quế, hồi và thảo mộc tự nhiên tạo nên mùi thơm dịu nhẹ không gây cay mắt. Cách đó không xa, những người thợ tại làng Tây Hồ vẫn tỉ mỉ chằm từng chiếc nón lá bài thơ với những vần lục bát ẩn hiện giữa hai lớp lá cọ mỏng khi soi dưới ánh mặt trời. Thay vì chỉ bán sản phẩm làm quà lưu niệm, các hộ dân mở rộng không gian trình diễn quy trình se hương, chằm nón để du khách trực tiếp thử sức. Thu nhập ổn định từ du lịch văn hóa giúp thế hệ trẻ địa phương tự hào tiếp nối nghề truyền thống của cha ông.",
    "referenceEn": "Just fifteen minutes from Hue's Imperial Citadel, Thuy Xuan incense village glows with vivid red, yellow, and purple bundles of incense sticks drying in the sun along quiet lanes. Crafting aromatic incense by hand here spans generations, blending cinnamon, star anise, and natural herbs for a gentle fragrance free of harsh smoke. Nearby, artisans in Tay Ho village still stitch delicate poetic conical hats, hiding folk verses between two thin palm-leaf layers visible only when held against sunlight. Rather than merely selling souvenirs, local families invite guests to try rolling incense paste and stitching palm brims themselves. Steady cultural tourism income encourages young locals to carry forward their ancestors' crafts with pride.",
