    "lengthTier": "medium",
    "wordCountVi": 164,
    "textVi": "Từng gắn liền với hình ảnh mái nhà giản dị nơi thôn quê, cây tre Việt Nam nay bước vào những công trình nhà hàng, nhà văn hóa cộng đồng và khu nghỉ dưỡng sinh thái tầm cỡ quốc tế. Qua quy trình ngâm bùn và xử lý nhiệt tự nhiên không hóa chất độc hại, thân tre đạt độ bền dẻo đáng kinh ngạc, đủ sức chống mối mọt và chịu bão gió vùng nhiệt đới. Nhờ kỹ thuật uốn cong và ghép chốt gỗ khéo léo, các kiến trúc sư tạo nên những mái vòm thoáng đãng đón gió tự nhiên mà không cần sử dụng bê tông cốt thép nặng nề. Những không gian mở tràn ngập ánh sáng này giúp giảm đáng kể chi phí làm mát và phát thải trong quá trình xây dựng. Hàng loạt giải thưởng kiến trúc quốc tế gần đây khẳng định giá trị đương đại của vật liệu bản địa thân thiện môi trường.",
    "referenceEn": "Once associated primarily with humble rural cottages, Vietnamese bamboo now shapes acclaimed pavilions, community halls, and eco-resorts recognized worldwide. Through traditional mud-soaking and chemical-free thermal treatment, bamboo poles gain remarkable structural toughness capable of resisting termites and tropical storms. Using skillful bending and wooden dowel joinery, architects weave airy vaulted canopies that capture natural breezes without relying on heavy steel-reinforced concrete. These sunlit open structures slash cooling electricity demand and construction carbon emissions dramatically. A string of recent international design honors underscores the contemporary power of sustainable native materials.",
