    "lengthTier": "long",
    "wordCountVi": 234,
    "textVi": "Trong một thập kỷ phát triển du lịch bùng nổ, nhiều dải san hô nông quanh quần đảo An Thới ở phía nam Phú Quốc từng chịu tổn thương nặng nề do neo tàu thiếu kiểm soát, rác thải nhựa và hiện tượng nước biển ấm lên. Trước nguy cơ mất dần vẻ đẹp đáy biển vốn là niềm tự hào của đảo ngọc, một nhóm nhà sinh học biển phối hợp cùng thợ lặn địa phương đã xây dựng các vườn ươm san hô nhân tạo dưới đáy vịnh. Thay vì chờ rạn tự nhiên phục hồi trong hàng chục năm, họ thu gom những nhánh san hô gãy còn sống sót sau bão, gắn cố định lên khung thép không gỉ và chăm sóc tảo bám định kỳ mỗi tuần. Khi từng cụm san hô phát triển cứng cáp sau hơn một năm, chúng được chuyển về cấy ghép trên những nền đá vôi trơ trụi, nhanh chóng kéo cá rạn và sinh vật biển quay trở lại trú ngụ. Song song với công tác kỹ thuật, chính quyền địa phương đặt phao neo cố định cho tàu du lịch và tập huấn hướng dẫn viên nhắc khách không giẫm đạp lên rạn khi lặn ngắm biển. Sự đồng lòng giữa nhà khoa học, ngư dân và doanh nghiệp đang dần trả lại sắc màu rực rỡ cho vùng biển Tây Nam.",
    "referenceEn": "During a decade of rapid tourism growth, shallow coral reefs circling the An Thoi archipelago south of Phu Quoc suffered heavy wear from careless boat anchors, plastic litter, and warming seawater. Facing the loss of the island's signature underwater beauty, marine biologists teamed up with local dive instructors to build artificial coral nurseries along sheltered bays. Rather than waiting decades for natural regrowth, divers rescue broken living fragments after storms, secure them onto rust-resistant steel frames, and scrub away competing algae weekly. Once colonies mature after roughly a year, teams transplant them onto barren reef limestone, swiftly drawing colorful reef fish and invertebrates back into shelter. Alongside underwater restoration, local authorities installed fixed mooring buoys for tour boats and trained guides to keep snorkelers from standing on living coral. Growing cooperation among scientists, fishers, and tour operators is steadily returning vibrant color to southwestern coastal waters.",
