    "textVi": "Mỗi sáng tinh mơ giữa tán rừng rậm Vườn quốc gia Cát Tiên, tiếng hót vang vọng hàng cây số của loài vượn đen má vàng báo hiệu ngày mới trong rừng nhiệt đới. Do loài linh trưởng đặc hữu này sống tít trên ngọn cây cao và rất nhạy cảm với bước chân con người, việc đếm bầy đàn bằng quan sát trực tiếp từng tốn nhiều công sức mà độ chính xác thấp. Những năm gần đây, kiểm lâm và nhà bảo tồn đã lắp đặt hàng chục máy ghi âm sinh học chống nước dọc các sườn dốc rừng sâu. Những cảm biến thông minh này thu âm liên tục suốt nhiều tháng, sau đó phần mềm tự động tách tần số tiếng gọi đặc trưng của từng gia đình vượn mà không xáo trộn sinh hoạt tự nhiên của chúng. Bản đồ phân bố chính xác giúp lực lượng bảo vệ rừng xác định kịp thời khu vực cần tuần tra gỡ bẫy và bảo vệ hành lang cây xanh nối liền các sinh cảnh bị chia cắt. Kết hợp công nghệ hiện đại với giáo dục cộng đồng vùng đệm đang tạo lá chắn vững chắc cho đa dạng sinh học miền Đông Nam Bộ.",
    "referenceEn": "At dawn inside the dense canopy of Cat Tien National Park, resonant calls of yellow-cheeked crested gibbons echo for kilometers across the tropical forest. Because these endangered primates live high in treetops and shy away from human footsteps, counting troops through visual surveys once demanded exhausting effort with low accuracy. Recently, park rangers and conservationists mounted dozens of weatherproof acoustic recorders along remote woodland ridges. These autonomous sensors capture forest soundscapes for months, allowing software to isolate each gibbon family's vocal signature without disturbing natural routines. Accurate distribution maps help rangers focus anti-poaching patrols and protect leafy corridors linking fragmented habitats. Pairing bioacoustic tools with buffer-zone outreach builds a stronger shield for southern Vietnam's biodiversity.",
